function trasforma(input){
  var tot = parseFloat(String(input.Totale).replace(/\./g, '').replace(',', '.'));
  var a = parseFloat(input.AliquotaIVA);
  var imp = Math.round(tot / (1 + a / 100) * 100) / 100, iva = Math.round((tot - imp) * 100) / 100;
  var s = /nota\s+(di\s+)?credito/i.test(input.TipoDocumento) ? -1 : 1;
  return { imponibile: s * imp, iva: s * iva, totale: s * tot };
}
